<?php
$pageTitle='Reportes administrativos';$basePath='../';require_once __DIR__.'/../auth.php';requireAdmin('../login.php','../usuario/index.php');require_once __DIR__.'/../firebase-data.php';
$period=normalizePeriod($_GET['period']??null,['today','day','month','year','range'],'today');$tz=new DateTimeZone('America/La_Paz');$now=new DateTimeImmutable('now',$tz);
$start=match($period){'day'=>(firebaseDate($_GET['from']??'')?->setTime(0,0)??$now->setTime(0,0)),'month'=>$now->modify('first day of this month')->setTime(0,0),'year'=>$now->setDate((int)$now->format('Y'),1,1)->setTime(0,0),'range'=>firebaseDate($_GET['from']??'')?->setTime(0,0)??$now->setTime(0,0),default=>$now->setTime(0,0)};
$end=match($period){'day'=>$start->setTime(23,59,59),'range'=>(firebaseDate($_GET['to']??'')?->setTime(23,59,59)??$now->setTime(23,59,59)),default=>$now};
$all=array_values(array_filter(firebaseRead(fn(FirebaseReadService $f)=>$f->collection('pedidos')), 'is_array'));$orders=array_values(array_filter($all,function(array $o)use($start,$end,$tz){$d=firebaseDate($o['fechaCreacion']??null);if(!$d)return false;$d=$d->setTimezone($tz);return $d>=$start&&$d<=$end;}));
$sales=array_values(array_filter($orders,fn($o)=>strtolower((string)($o['estadoPago']??''))==='aprobado'&&strtolower((string)($o['estado']??''))!=='cancelado'&&strtolower((string)($o['metodoPago']??''))!=='admin'));
$total=array_sum(array_map(fn($o)=>(float)($o['total']??0),$sales));$products=[];$presentations=[];$payments=[];$origins=[];
foreach($sales as $o){$payments[(string)($o['metodoPago']??'No especificado')]=($payments[(string)($o['metodoPago']??'No especificado')]??0)+1;$origin=orderOrigin($o);$origins[$origin]=($origins[$origin]??0)+1;foreach(orderItems($o) as $item){if(!is_array($item))continue;$name=(string)($item['nombre']??'Sin detalle');$q=(int)($item['cantidad']??1);$products[$name]=($products[$name]??0)+$q;$size=(string)($item['cantidadMl']??'Sin datos').' ml';$presentations[$size]=($presentations[$size]??0)+$q;}}
arsort($products);$top=array_key_first($products);require __DIR__.'/../header.php';require __DIR__.'/../navbar.php';
?>
<main id="contenido" class="admin-page reports-page"><section class="admin-head"><div class="container"><div><span class="eyebrow eyebrow--light">Administración · Reportes reales</span><h1>Reportes CHICHEJ</h1><p>Ventas válidas: pago aprobado, pedido no cancelado y método distinto de admin.</p></div><a class="button button--outline-light" href="index.php">Volver al panel</a></div></section><section class="section section--cream"><div class="container"><form class="report-toolbar" method="get"><div class="report-periods"><button name="period" value="today" class="<?=$period==='today'?'is-active':''?>">Hoy</button><button name="period" value="day" class="<?=$period==='day'?'is-active':''?>">Día</button><button name="period" value="month" class="<?=$period==='month'?'is-active':''?>">Mes</button><button name="period" value="year" class="<?=$period==='year'?'is-active':''?>">Año</button><button name="period" value="range" class="<?=$period==='range'?'is-active':''?>">Rango</button></div><div class="report-range"><label>Desde <input type="date" name="from" value="<?=h($start->format('Y-m-d'))?>"></label><label>Hasta <input type="date" name="to" value="<?=h($end->format('Y-m-d'))?>"></label><button class="button button--ghost" type="submit">Vista previa</button><button class="button button--primary" type="button" disabled>Generar PDF</button></div></form><div class="report-context"><span class="status-pill status-pill--active">● Firestore · <?=h($start->format('d/m/Y'))?>–<?=h($end->format('d/m/Y'))?></span><p>Sin escrituras ni generación PDF.</p></div><div class="report-metrics"><article><small>Total de ventas</small><strong><?=h(money($total))?></strong><span><?=count($sales)?> ventas válidas</span></article><article><small>Pedidos</small><strong><?=count($orders)?></strong><span>Incluidos en el período</span></article><article><small>Producto más vendido</small><strong><?=h($top??'Sin datos')?></strong><span><?=$top?h($products[$top]).' unidades':'Sin ventas válidas'?></span></article><article><small>Ticket promedio</small><strong><?=h($sales?money($total/count($sales)):'Sin datos')?></strong><span>Sobre ventas válidas</span></article></div><div class="report-grid"><section class="report-card"><h2>Resumen por presentación</h2><ul class="report-channels"><?php foreach($presentations as $k=>$v):?><li><span><?=h($k)?></span><b><?=$v?></b></li><?php endforeach;?><?php if(!$presentations):?><li>Sin datos</li><?php endif;?></ul></section><section class="report-card"><h2>Ventas por origen</h2><ul class="report-channels"><?php foreach($origins as $k=>$v):?><li><span><?=h($k)?></span><b><?=$v?></b></li><?php endforeach;?><?php if(!$origins):?><li>Sin datos</li><?php endif;?></ul></section><section class="report-card"><h2>Métodos de pago</h2><ul class="report-channels"><?php foreach($payments as $k=>$v):?><li><span><?=h($k)?></span><b><?=$v?></b></li><?php endforeach;?><?php if(!$payments):?><li>Sin datos</li><?php endif;?></ul></section><section class="report-card"><h2>Pedidos incluidos</h2><div class="data-list data-list--compact"><?php foreach($orders as $o):?><div><b><?=h($o['pedidoId']??$o['_id'])?></b><span><?=h(orderOrigin($o))?></span><span><?=h(orderSummary($o))?></span><strong><?=h(money($o['total']??null))?></strong></div><?php endforeach;?><?php if(!$orders):?><p>Sin pedidos en el período.</p><?php endif;?></div></section></div></div></section></main>
